    "common.verified": "Verificado",
    "common.transparent": "Transparente",
    "common.details": "Ver detalles →",
    "common.synthetic_data": "Datos sintéticos.",
    "common.synthetic_desc": "Los pacientes, identificadores y valores numéricos de esta página son ficticios y se usan únicamente con fines ilustrativos y comerciales. No representan a personas reales ni deben usarse como referencia clínica.",
    "hero.eyebrow": "🚀 Dossier Técnico-Comercial • SaaS Clínico CDSS & Medicina de Precisión",
    "hero.title": "Plataforma PK-Bayes: Dosificación Farmacocinética de Precisión, MAP & Aprendizaje Adaptativo",
    "hero.lead": "Solución Software as a Service (SaaS) médica de vanguardia diseñada para la optimización individualizada de dosis de fármacos de estrecho margen terapéutico (<strong>Vancomicina</strong> y <strong>Fenitoína</strong>). Transforma el Monitoreo Terapéutico (TDM) en un entorno predictivo dinámico impulsado por estimación bayesiana MAP, resolución de ODEs ante falla renal aguda y aprendizaje institucional en tiempo real.",
    "hero.chip_directors": "🏥 Directores Médicos",
