    "drugs.hero_lead": "PK-Bayes optimiza hoy la monitorización y dosificación de precisión de <strong>Vancomicina</strong> (cinética lineal bicompartimental y ODEs continuas) y avanza en el desarrollo e integración de <strong>Fenitoína</strong> (cinética saturable de Michaelis-Menten).",
