    "cases.case1_title": "Vancomicina en Falla Renal Aguda Dinámica (AKI) y Recuperación",
    "cases.case1_desc": "Paciente sintético #482 — 68 años, varón, 82 kg, ingreso en UCI por sepsis respiratoria con creatinina fluctuante (1.1 → 1.6 → 2.4 → 1.8 mg/dL).",
    "cases.c1_step1_t": "Ingreso y Dosificación Empírica Guiada por AUC",
    "cases.c1_step1_d": "Se registra peso, talla y creatinina sérica inicial (1.1 mg/dL, ClCr 72 mL/min). PK-Bayes propone dosis de carga de 25 mg/kg y mantenimiento de 1000 mg q12h basado en Goti et al. 2018.",
    "cases.c1_step2_t": "Deterioro Renal (AKI) y TDM a las 24h",
    "cases.c1_step2_d": "La creatinina asciende a 1.6 mg/dL. Se extrae nivel TDM aleatorio a las 24h (18.4 mg/L). PK-Bayes resuelve por tramos mediante ODEs preservando la masa acumulada.",
    "cases.c1_step3_t": "Recálculo Bayesiano MAP Instantáneo",
    "cases.c1_step3_d": "El motor actualiza los parámetros individuales en < 100 ms: el aclaramiento individual cae a CL = 2.65 L/h evitando una sobredosis inminente.",
    "cases.c1_step4_t": "Simulación What-If y Ajuste de Prescripción",
    "cases.c1_step4_d": "Se ajusta la dosis a 750 mg q12h logrando un AUC24/CIM de 485 mg·h/L dentro del rango de máxima eficacia y seguridad.",
