    "cases.c2_s1_d": "El intensivista ingresa los parámetros técnicos del circuito: Tasa de Efluente = 2.340 mL/h (30 mL/kg/h), Coeficiente de Tamizado del filtro polisulfona S = 0.80 y Aclaramiento residual = 0 L/h (anuria).",
    "cases.c2_s2_t": "Cálculo Dinámico de Aclaramiento Extracorpóreo",
    "cases.c2_s2_d": "Al 3er día se extrae nivel plasmático pre-dosis reportando 19.8 mg/L. La relación AUC24/CIM calculada por cinética clásica supera 620 mg·h/L.",
    "cases.c2_s3_t": "Prescripción Óptima sin Riesgo de Subdosificación",
    "cases.c2_s3_d": "Los nomogramas convencionales subdosifican a estos pacientes al tratarlos como \"falla renal terminal estándar\". PK-Bayes propone una dosis de carga de 1.750 mg seguida de 1.000 mg cada 24h, logrando AUC24 de 510 mg·h/L y control rápido de la bacteriemia.",
    "cases.c2_s4_t": "Optimización Posológica a 500 mg q12h",
    "cases.c2_s4_d": "Se reajusta el régimen a 500 mg q12h en infusión de 1 hora, proyectando AUC24 de 468 mg·h/L con excelente evolución clínica y sin toxicidad renal.",
    "cases.c3_eyebrow": "Caso 3 · Nefrología & Hemodiálisis Intermitente",
    "cases.c3_title": "Vancomicina en Paciente Crítico en Hemodiálisis Intermitente (IHD)",
    "cases.c3_desc": "Paciente sintético #305 — 59 años, varón, 70 kg, sepsis por catéter de diálisis, en programa de HD 3 veces por semana.",
    "cases.c3_s1_t": "Dosis de Carga Previa a la Primera Sesión",
    "cases.c3_s1_d": "Se administra dosis de carga de 1750 mg (25 mg/kg). En anuria total, el aclaramiento depende exclusivamente de la extracción durante la sesión de HD.",
    "cases.c3_s2_t": "Modelado de Extracción en Sesión de HD (4 horas)",
    "cases.c3_s2_d": "PK-Bayes incorpora el flujo de sangre (Qb = 300 mL/min) y coeficiente de extracción del dializador, calculando una caída del 45% en la concentración plasmática.",
    "cases.c3_s3_t": "Cálculo de Suplementación Post-Diálisis Exacta",
    "cases.c3_s3_d": "El módulo de IHD proyecta la dosis de mantenimiento suplementaria de 500 mg administrada en la última hora de diálisis o inmediatamente post-procedimiento.",
    "cases.c3_s4_t": "Mantenimiento del Target Terapéutico en Periodo Inter-dialítico",
    "cases.c3_s4_d": "El AUC24 proyectado en los días sin diálisis se mantiene en 440–520 mg·h/L, asegurando erradicación bacteriana sin sobrecarga tóxica.",
    "pricing.faq_h_eyebrow": "Preguntas Frecuentes",
    "pricing.faq_h_title": "Todo lo que necesitas saber antes de empezar",
    "pricing.faq1_q": "¿Qué incluye la prueba gratuita de 15 días?",
    "pricing.faq1_a": "La prueba gratuita permite conocer las principales herramientas de PK-Bayes durante 15 días, sin pago inicial ni suscripción automática.",
    "pricing.faq2_q": "¿Qué ventajas ofrece el Plan Completo (1.350 USD/año)?",
    "pricing.faq2_a": "El Plan Completo otorga acceso total e ilimitado para toda tu institución hospitalaria o universitaria: usuarios y pacientes ilimitados, calibración de priors institucionales locales con las métricas de tu centro (RMSE/Bias), soporte prioritario y la <strong>generación y descarga ilimitada de bases de datos PopPK estructuradas para NONMEM y Monolix</strong>.",
    "pricing.faq3_q": "¿Cómo se compara PK-Bayes frente a otros softwares internacionales?",
    "pricing.faq3_a": "PK-Bayes proporciona estimación bayesiana MAP con modelos de 2 compartimentos y resolución ODE Runge-Kutta 45 continua preservando masa, añadiendo dos innovaciones clave: la <strong>calibración de priors adaptativos propios</strong> de tu hospital y la <strong>exportación directa para farmacometría PopPK</strong>. Además, somos el <strong>software más económico del mercado, sin trucos y con soporte personalizado</strong>, a una fracción del costo de soluciones internacionales que cobran entre $15.000 y $50.000+ USD anuales.",
    "pricing.faq4_q": "¿El software sustituye la decisión del farmacéutico o médico?",
    "pricing.faq4_a": "No. PK-Bayes es un sistema de apoyo a la decisión clínica (CDSS). Proporciona cálculos matemáticos y curvas proyectadas para fundamentar la decisión terapéutica, pero la prescripción y validación final es siempre responsabilidad del equipo sanitario a cargo del paciente.",
    "pricing.faq5_q": "¿Puedo cancelar en cualquier momento?",
    "pricing.faq5_a": "Sí. La suscripción al Plan Completo es anual sin contratos de permanencia forzosa. Puedes cancelar la renovación automática en cualquier momento antes de la fecha de vencimiento.",
