    "func.flow_step3_d": "Genera la curva de concentración continua individualizada y entrega CL, V₁, Q, V₂, t½ y AUC₂₄ con intervalos de confianza y coeficiente de variación (CV%).",
    "func.m1_main_title": "Estimación Bayesiana MAP en Tiempo Real (Maximum A Posteriori)",
    "func.m1_main_desc": "Resuelve el compromiso matemático óptimo entre el prior poblacional y las concentraciones séricas medidas del paciente, entregando de forma instantánea CL, V₁, Q, V₂, t½ y AUC₂₄.",
    "func.m1_list_b1": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Modelos bicompartimentales robustos:</strong> Goti et al. (2018) con acotamiento de variabilidad interindividual (BSV) en V₁ (~30%) para evitar sobreajuste ante muestreos de 1 nivel valle.",
    "func.m1_list_b2": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Transparencia trifásica:</strong> Visualiza en la misma interfaz los valores <em>Individual</em>, <em>Poblacional</em> e <em>Institucional</em>.",
    "func.m1_list_b3": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Gráficos interactivos:</strong> Curva de concentración vs. tiempo con visualización de rango terapéutico, niveles observados e intervalos de confianza.",
