    "pricing.feat_renal": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> Cinética renal dinámica CL(t) y soporte de diálisis / TRRC",
