    "pricing.feat_nopoppk": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" style=\"color:var(--text-muted)\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> <em>No incluye descarga de bases de datos PopPK</em>",
    "pricing.feat_nocredit": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> Sin tarjeta de crédito requerida · Expira en 15 días",
    "pricing.feat_comp_unlimited": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Acceso 100% completo e ilimitado para toda la institución</strong>",
