    "pricing.feat_comp_poppk": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Descarga y exportación de bases de datos PopPK (NONMEM y Monolix)</strong>",
