    "cases.case1_desc": "Synthetic Patient #482 — 68-year-old male, 82 kg, admitted to ICU for septic pneumonia with fluctuating serum creatinine (1.1 → 1.6 → 2.4 → 1.8 mg/dL).",
    "cases.c1_step1_t": "Admission and AUC-Guided Empirical Dosing",
    "cases.c1_step1_d": "Baseline weight, height, and serum creatinine are recorded (1.1 mg/dL, CrCl 72 mL/min). PK-Bayes suggests a 25 mg/kg loading dose and 1000 mg q12h maintenance based on Goti et al. 2018.",
    "cases.c1_step2_t": "Renal Deterioration (AKI) and 24h TDM Level",
    "cases.c1_step2_d": "Creatinine climbs to 1.6 mg/dL. A random 24h TDM level reports 18.4 mg/L. PK-Bayes integrates piecewise dynamic ODEs preserving cumulative body drug mass.",
    "cases.c1_step3_t": "Instant MAP Bayesian Recalculation",
    "cases.c1_step3_d": "Individual clearance drops to CL = 2.65 L/h in <100 ms. Continuing 1000 mg q12h would project severe drug overaccumulation (AUC24 > 680 mg·h/L).",
    "cases.c1_step4_t": "What-If Simulation and Regimen Optimization",
    "cases.c1_step4_d": "The clinician simulates 750 mg q12h, projecting steady-state AUC24/MIC of 485 mg·h/L and trough 16.2 mg/L, achieving target efficacy while preserving renal function.",
