    "cases.c2_eyebrow": "Case 2 · Inpatient Medicine & Bi-Compartmental Modeling",
    "cases.c2_title": "Vancomycin in Septic Shock and Continuous Hemodiafiltration",
    "cases.c2_desc": "Synthetic Patient #719 — 74-year-old female, 58 kg, severe pneumonia, baseline serum creatinine 0.9 mg/dL (CrCl 46 mL/min).",
    "cases.c2_s1_t": "Extracorporeal Circuit Parameterization",
    "cases.c2_s1_d": "The intensivist inputs circuit parameters: Effluent Rate = 2,340 mL/h (30 mL/kg/h), Polysulfone Filter Sieving Coefficient S = 0.80, and Residual Renal Clearance = 0 L/h (anuria).",
    "cases.c2_s2_t": "Dynamic Calculation of Extracorporeal Clearance",
    "cases.c2_s2_d": "On Day 3, a pre-dose trough level returns at 19.8 mg/L. Traditional linear formulas project an excessive AUC24 > 620 mg·h/L.",
    "cases.c2_s3_t": "Optimal Dosing Without Underdosing Risk",
    "cases.c2_s3_d": "Conventional nomograms severely underdose these patients by treating them as standard end-stage renal failure. PK-Bayes calculates a 1,750 mg loading dose followed by 1,000 mg every 24h, achieving an AUC24 of 510 mg·h/L and rapid bacteremia clearance.",
    "cases.c2_s4_t": "Dose Optimization to 500 mg q12h",
    "cases.c2_s4_d": "Regimen adjusted to 500 mg q12h over 1 hour infusion, projecting target steady-state AUC24 of 468 mg·h/L with excellent recovery and zero nephrotoxicity.",
    "cases.c3_eyebrow": "Case 3 · Nephrology & Intermittent Hemodialysis",
    "cases.c3_title": "Vancomycin in a Critical Care Patient on Intermittent Hemodialysis (IHD)",
    "cases.c3_desc": "Synthetic Patient #305 — 59-year-old male, 70 kg, dialysis catheter bloodstream infection, on thrice-weekly maintenance hemodialysis.",
    "cases.c3_s1_t": "Loading Dose Prior to First Dialysis Session",
    "cases.c3_s1_d": "Administered 1750 mg (25 mg/kg) loading dose. In complete anuria, drug clearance depends entirely on dialyzer membrane clearance.",
    "cases.c3_s2_t": "Modeling 4-Hour Dialysis Session Extraction",
    "cases.c3_s2_d": "PK-Bayes incorporates dialyzer blood flow (Qb = 300 mL/min) and membrane extraction ratio, computing a 45% intra-dialytic concentration drop.",
    "cases.c3_s3_t": "Precise Post-Dialysis Supplemental Dose Calculation",
    "cases.c3_s3_d": "The IHD engine projects an exact 500 mg post-dialysis supplemental maintenance dose infused during the final hour of dialysis.",
    "cases.c3_s4_t": "Target Exposure Maintained Throughout Inter-Dialytic Days",
    "cases.c3_s4_d": "Projected AUC24 on non-dialysis days remains stable at 440–520 mg·h/L, securing bacterial eradication without toxic accumulation.",
    "pricing.faq_h_eyebrow": "Frequently Asked Questions",
    "pricing.faq_h_title": "Everything you need to know before getting started",
    "pricing.faq1_q": "What is included in the 14-day free trial?",
    "pricing.faq1_a": "The 14-day free trial grants unrestricted access to all clinical tools: real-time MAP Bayesian estimation, What-If dose predictor, dynamic renal clearance adjustments CL(t), hemodialysis/CRRT support, and cohort dashboards. The only restriction is that <strong>it does not include PopPK dataset downloads (NONMEM/Monolix) or institutional prior calibrations</strong>. No credit card required, automatically expires after 14 days.",
    "pricing.faq2_q": "What are the advantages of the Complete Plan ($1,350 USD/year)?",
    "pricing.faq2_a": "The Complete Plan delivers unrestricted institutional access: unlimited clinical users and patient profiles, local hospital prior calibration with real-time audit metrics (RMSE/Bias), priority support, and <strong>unlimited structured PopPK dataset exports for NONMEM and Monolix</strong>.",
    "pricing.faq3_q": "How does PK-Bayes compare to legacy international software?",
    "pricing.faq3_a": "PK-Bayes provides robust 2-compartment MAP Bayesian estimation and continuous ODE Runge-Kutta 45 solvers preserving drug mass, featuring two game-changing innovations: <strong>adaptive institutional prior calibration</strong> and <strong>1-click PopPK research dataset export</strong>. Moreover, it is the <strong>most affordable precision dosing software on the market</strong>, at a fraction of legacy solutions charging $15,000 to $50,000+ USD annually.",
    "pricing.faq4_q": "Does PK-Bayes replace clinical judgment?",
    "pricing.faq4_a": "No. PK-Bayes is a Clinical Decision Support System (CDSS). It supplies rigorous mathematical predictions to guide therapeutic dosing, but final prescription and clinical responsibility always rest with the licensed healthcare team.",
    "pricing.faq5_q": "Can I cancel at any time?",
    "pricing.faq5_a": "Yes. The Complete Plan is an annual subscription without lock-in contracts. You can cancel automatic renewal at any time prior to your expiration date.",
