    "cases.c_pheny_desc": "Simulation of the upcoming Phenytoin module — ICU patient with hypoalbuminemia (2.4 g/dL) and total serum concentration apparently \"within therapeutic range\".",
    "cases.c_pheny_s1_t": "Deceptively Normal Total Level",
    "cases.c_pheny_s1_d_html": "A total phenytoin level of <strong>14.0 mg/L</strong> is reported (reference range 10–20 mg/L), which in conventional monitoring creates a false sense of therapeutic safety.",
