    "func.flow_step1_t": "📥 Population / Hospital Prior",
    "func.flow_step1_d": "Loads the validated pharmacokinetic model (Goti 2-Comp, Rodvold, Thomson, Yamamoto, or the hospital-calibrated Institutional Prior).",
    "func.flow_step2_badge": "Phase 02 • Flexible Serum Sampling",
    "func.flow_step2_t": "🧪 1 or 2 Measured Plasma Levels",
    "func.flow_step2_d": "No rigid trough/peak sampling constraints: the algorithm places the sample at any time during the infusion interval with full mathematical rigor.",
    "func.flow_step3_badge": "Phase 03 • Fitting & Predictor",
    "func.flow_step3_t": "⚙️ Posterior Output (< 100 ms)",
    "func.flow_step3_d": "Generates the individualized continuous concentration curve and delivers CL, V₁, Q, V₂, t½, and AUC₂₄ with confidence intervals and coefficient of variation (CV%).",
    "func.m1_main_title": "Real-Time Bayesian MAP Estimation (Maximum A Posteriori)",
    "func.m1_main_desc": "Solves the optimal mathematical trade-off between the population prior and the patient's measured serum concentrations, instantly delivering CL, V₁, Q, V₂, t½, and AUC₂₄.",
    "func.m1_list_b1": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Robust two-compartment models:</strong> Goti et al. (2018) with bounded inter-individual variability (BSV) on V₁ (~30%) to prevent overfitting with single trough sampling.",
    "func.m1_list_b2": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Three-phase transparency:</strong> Visualize <em>Individual</em>, <em>Population</em>, and <em>Institutional</em> values side by side in the same interface.",
    "func.m1_list_b3": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>Interactive charts:</strong> Concentration vs. time curve with therapeutic range visualization, observed levels, and confidence intervals.",
    "func.m2_header_badge": "Module 02 • Dosing Simulation",
    "func.m2_header_title": "Dosing Regimen Predictor & What-If Simulation",
    "func.m2_header_desc": "Simulate any dosing regimen (mg), interval (τ = 6, 8, 12, 24, 36, 48h, or 24h continuous infusion) and instantly observe projected steady-state concentrations.",
    "func.m2_sim_badge": "Interactive Clinical Simulator",
    "func.m2_sim_title": "What-If Regimen Explorer — Vancomycin",
