    "hero.eyebrow": "🚀 技术与商业说明书 • 临床 CDSS SaaS & 精准医学工作站",
    "hero.title": "PK-Bayes 平台：精准药代动力学剂量设计、MAP 贝叶斯估算与自适应学习",
    "hero.lead": "专为窄治疗窗药物（<strong>万古霉素</strong>与<strong>苯妥英钠</strong>）个体化给药剂量优化而打造的顶尖临床 SaaS 系统。依托 MAP 贝叶斯估算、急性肾损伤 (AKI) 质量守恒常微分方程 (ODE) 数值解析及医院本土自适应学习，将传统血药浓度监测 (TDM) 全面升级为动态预测工作站。",
    "hero.chip_directors": "🏥 医疗副院长 / 医教处",
