    "hero.stat_export_num": "1 键导出",
    "hero.stat_export_label": "PopPK NONMEM 数据集",
    "hero.stat_security_num": "100%",
    "hero.stat_security_label": "金融级数据隔离",
    "hero.stat_tdm_status": "TDM 状态：<strong style=\"color:var(--green-dark)\">实时精准优化中</strong>",
