    "algo.eyebrow": "第 2 节 • 核心算法",
    "algo.title": "MAP 贝叶斯数学优化引擎与自适应 ODE RK45 求解器",
    "algo.lead": "结合 L-BFGS-B 高性能优化算法与自适应步长常微分方程数值求解，展现临床药动学工程的极致严谨。",
    "algo.step1_badge": "步骤 01 • 临床与群体参数输入",
    "algo.step1_title": "📥 群体先验分布 + 患者个体参数",
    "algo.step1_desc": "无缝整合国际公认的群体先验参数 (Priors) 与患者人口统计学指标、动态肾功能及实测血药浓度数据。",
    "algo.step2_badge": "步骤 02 • 确定性优化求解",
    "algo.step2_title": "⚙️ MAP 核心计算 (L-BFGS-B + ODE RK45)",
    "algo.step2_desc": "通过严格质量守恒定律求解多室常微分方程 A₁(t)、A₂(t)，在毫秒内精准拟合出个体化药动学参数 (CL, V₁, Q, V₂, t₁/₂)。",
    "algo.step3_badge": "步骤 03 • 处方预测与剂量推荐",
    "algo.step3_title": "📈 个体化药时曲线 + 剂量/AUC₂₄ 预测器",
    "algo.step3_desc": "生成平滑连续的个体化药时浓度曲线，并支持即时 What-If 模拟以快速锁定达到治疗窗的最佳给药方案。",
    "pk.eyebrow": "第 3 节 • 高级药动学建模",
    "pk.title": "万古霉素（线性药动学）与苯妥英钠（Michaelis-Menten 饱和代谢）",
    "pk.lead": "全面支持国际公认的房室模型，并内置遵循 2020 ASHP/IDSA 共识指南的经验性给药计算器。",
    "pk.vanco_badge": "已上线模块",
    "pk.vanco_consensus": "2020 ASHP/IDSA 指南",
    "pk.vanco_title": "A. 万古霉素（单室与双室模型）",
    "pk.vanco_desc": "以 AUC₂₄/MIC = 400–600 mg·h/L 为目标的高精度药动学模拟。",
    "pk.vanco_item1": "<strong>Goti et al. (2018)：</strong> 采用约束双室模型，限定 V₁ 个体间变异 (BSV ~30%)，在稀疏采血下保持计算高度稳健。",
    "pk.vanco_item2": "<strong>Rodvold et al. (1988)：</strong> 专为成人住院患者优化的经典双室模型。",
    "pk.vanco_item3": "<strong>Thomson & Yamamoto：</strong> 根据体重与动态肌酐清除率精确调整的多室动力学模型。",
    "pk.pheny_badge": "深度研发中",
    "pk.pheny_consensus": "非线性饱和动力学",
    "pk.pheny_title": "B. 苯妥英钠（Michaelis-Menten 动力学）",
    "pk.pheny_desc": "精准模拟肝脏酶饱和代谢过程 (Vₘₐₓ, Kₘ) 以预测稳态血药浓度 Cₛₛ。",
    "pk.pheny_item1": "<strong>酶饱和动力学：</strong> 准确预测日剂量微调时稳态血药浓度的非线性跃升。",
    "pk.pheny_item2": "<strong>Sheiner-Tozer 差异化算法：</strong> 根据血清白蛋白浓度自动校正游离药物浓度比例。",
    "pk.pheny_item3": "<strong>透析亚群优化：</strong> 针对终末期肾病 (ESRD) 与间歇性血液透析患者采用专属动力学校正常数。",
    "calc.live_badge": "实时交互计算工具",
    "calc.target_badge": "目标靶值：AUC₂₄/MIC 400–600 mg·h/L",
