    "pricing.faq_h_eyebrow": "常见问题解答",
    "pricing.faq_h_title": "在开启使用前，您可能关心的所有问题",
    "pricing.faq1_q": "14 天免费试用包含哪些功能？",
    "pricing.faq1_a": "免费试用让您在 14 天内无限制体验所有临床工具：实时 MAP 贝叶斯估算、What-If 剂量预测、动态肾清除率 CL(t) 调整、血液透析/CRRT 支持及患者队列看板。唯一的限制是<strong>不包含 PopPK 科研数据集导出（NONMEM/Monolix）及本院专属 Prior 校准功能</strong>。无需绑定信用卡，到期自动结束。",
    "pricing.faq2_q": "全功能尊享版（1,350 美元/年）有哪些核心优势？",
    "pricing.faq2_a": "全功能版提供全院机构无限制授权：无限制医护与药师账号、无限制患者档案、本院专属 Prior 自适应校准（RMSE/Bias 质控）、优先技术支持以及<strong>无限次导出用于 NONMEM 和 Monolix 的标准化 PopPK 科研数据集</strong>。",
    "pricing.faq3_q": "PK-Bayes 与国际同类传统商业软件相比有何优势？",
    "pricing.faq3_a": "PK-Bayes 采用双室 MAP 贝叶斯估算与 Runge-Kutta 45 质量守恒常微分方程求解，更带来两大开创性创新：<strong>医院本土 Prior 自适应校准</strong>与<strong>一键 PopPK 科研数据集直出</strong>。此外，我们是<strong>市场上性价比最高、透明无套路且配备专业支持的系统</strong>，费用仅为每年收取 1.5 万至 5 万美元以上国外传统软件的一小部分。",
    "pricing.faq4_q": "本软件是否会替代临床医师或药师的独立决策？",
    "pricing.faq4_a": "不会。PK-Bayes 属于临床决策支持系统 (CDSS)。系统提供科学的数学计算与预测曲线作为参考依据，最终的处方权与临床责任始终由主管医护团队承担。",
    "pricing.faq5_q": "可以随时取消后续续费吗？",
    "pricing.faq5_a": "可以。全功能版为年度授权，无任何强制捆绑合约。您可以在到期前随时取消下一年度的自动续订。",
