    "pricing.faq_block_1": "免费试用让您在14天内免费使用平台所有临床工具：实时贝叶斯MAP估计、What-If模拟、动态肾清除率CL(t)调整、血液透析/CRRT支持和纵向队列仪表盘。主要限制是<strong>不包含PopPK数据库下载/导出和您机构自有的机构模型</strong>。无需信用卡，14天后自动过期。",
    "pricing.faq_block_2": "完整计划为您的整个医院或大学机构提供完全无限制访问：无限用户和患者、使用中心指标（RMSE/Bias）校准本地机构Prior、优先支持，以及<strong>无限生成和下载用于NONMEM和Monolix的结构化PopPK数据库</strong>。",
    "pricing.faq_block_3": "PK-Bayes提供贝叶斯MAP估计，采用2室模型和连续Runge-Kutta 45 ODE求解并保持质量守恒，并增加两项关键创新：<strong>校准您医院自己的自适应Prior</strong>和<strong>PopPK药物计量学直接导出</strong>。此外，我们是<strong>市场上最经济实惠的软件，无套路且提供个性化支持</strong>，成本仅为国际解决方案的零头（年费$15,000至$50,000+美元）。",
    "pricing.faq_block_4": "不会。PK-Bayes 是临床决策支持系统 (CDSS)。它提供数学计算和预测曲线以支持治疗决策，但最终处方和验证始终是负责患者的医疗团队的责任。",
    "pricing.faq_block_5": "是的。完整计划的订阅为年度制，无强制续约合同。您可以在到期日前随时取消自动续订。",
