    "cases.c2_s2_t": "体外クリアランスの動的算出",
    "cases.c2_s2_d": "投与3日目のトラフ濃度は 19.8 mg/L。従来法による推定では AUC24 > 620 mg·h/L となり腎毒性リスクが示唆。",
