    "cases.c2_s3_d": "従来のノモグラムは末期腎不全として過小投与に陥りがちです。PK-Bayes は負荷量 1,750 mg、以降 24時間毎 1,000 mg を提案し、AUC24 510 mg·h/L で速やかな菌血症制御を実現。",
    "cases.c2_s4_t": "500 mg q12h への処方最適化",
    "cases.c2_s4_d": "500 mg q12h（1時間点滴）へ減量し、目標定常状態 AUC24 468 mg·h/L を達成。腎障害を起こさず治癒。",
    "cases.c3_eyebrow": "事例 3 · 腎臓内科 & 間欠的血液透析 (IHD)",
