    "cases.c3_desc": "模擬患者 #305 — 59歳男性、70 kg、透析カテーテル血流感染症、週3回の維持血液透析中。",
    "cases.c3_s1_t": "第1回透析施行前の負荷投与",
    "cases.c3_s1_d": "1750 mg (25 mg/kg) の負荷量を投与。完全無尿状態のため、薬物消失は透析器による体外クリアランスのみに依存。",
    "cases.c3_s2_t": "4時間の透析セッション中の動態モデリング",
    "cases.c3_s2_d": "血流量 (Qb = 300 mL/min) とダイアライザー膜除去率を考慮し、透析セッション中の約 45% の濃度低下を正確に計算。",
    "cases.c3_s3_t": "透析後補充投与量の精密算出",
    "cases.c3_s3_d": "透析終了前1時間または終了直後に投与すべき 500 mg の維持補充量を算出。",
    "cases.c3_s4_t": "非透析日における目標濃度の維持",
    "cases.c3_s4_d": "非透析日の予測 AUC24 は 440–520 mg·h/L で推移し、毒性蓄積を起こさず確実な殺菌効果を維持。",
    "pricing.faq_h_eyebrow": "よくあるご質問",
    "pricing.faq_h_title": "ご導入前にご確認いただけるすべての疑問点",
    "pricing.faq1_q": "14日間の無料トライアルには何が含まれますか？",
    "pricing.faq1_a": "14日間の無料トライアルでは、リアルタイム MAP ベイズ推定、What-If 投与予測、動的腎クリアランス CL(t) 解析、血液透析/CRRT 対応、コホートダッシュボードなどすべての臨床機能を制限なくご利用いただけます。唯一の制限は、<strong>PopPK 研究用データセット出力 (NONMEM/Monolix) および自院 Prior 自動校正が含まれない点</strong>です。クレジットカード登録は不要で、14日後に自動終了します。",
    "pricing.faq2_q": "施設完全プラン（年間 1,350 USD）のメリットは何ですか？",
    "pricing.faq2_a": "施設完全プランは、全施設無制限ユーザー・無制限患者登録、自院 Prior 自動校正（RMSE/Bias 評価）、優先サポート、そして <strong>NONMEM & Monolix 向け標準 PopPK データセットの無制限出力</strong>を含む完全パッケージです。",
    "pricing.faq3_q": "従来の海外製ソフトウェアとの違いは何ですか？",
    "pricing.faq3_a": "PK-Bayes は高精度な 2室 MAP ベイズ推定と質量保存型ルンゲ＝クッタ 45 微分方程式求解を備え、さらに<strong>自院適応型 Prior 校正</strong>と<strong>PopPK データセット即時出力</strong>という2つの独自技術を搭載しています。さらに、年間 15,000〜50,000 ドル以上を請求する海外製ツールに比べ、<strong>圧倒的に明瞭かつ導入しやすい価格体系</strong>を実現しています。",
    "pricing.faq4_q": "ソフトウェアが医師や薬剤師の臨床判断に代わることはありますか？",
    "pricing.faq4_a": "いいえ。PK-Bayes は臨床意思決定支援システム (CDSS) です。科学的計算と予測曲線により処方設計を支援しますが、最終的な処方決定と臨床責任は常に担当の医療従事者が負います。",
    "pricing.faq5_q": "契約はいつでも解約できますか？",
    "pricing.faq5_a": "はい。施設完全プランは年間契約であり、長期拘束はありません。次回更新日前にいつでも管理画面から自動更新を解除できます。",
    "gracias.h1_confirmed": "お申込み・決済が完了しました",
