    "func.m1_main_desc": "母集団プライオルと患者の実測血清濃度間の最適な数学的トレードオフを解き、CL、V₁、Q、V₂、t½、AUC₂₄ を即座に出力。",
    "func.m1_list_b1": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>頑健な2コンパートメントモデル：</strong>Goti et al. (2018) V₁の個体間変動(BSV)を~30%に制限し、単一トラフサンプリングでの過適合を防止。",
    "func.m1_list_b2": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>三相透明性：</strong>同一インターフェースで<em>個別</em>・<em>母集団</em>・<em>施設</em>の各値を並べて表示。",
    "func.m1_list_b3": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M20 6 9 17l-5-5\"/></svg> <strong>インタラクティブチャート：</strong>濃度-時間曲線に治療域、実測値、信頼区間を表示。",
