    "func.m4_c_multi_t": "マルチセレクション＆クロストレーサビリティ",
    "func.m4_c_multi_d": "1人、2人、または複数の患者を選択。ホバー時に両パネルで異なる臨床カラーで軌跡をハイライト。",
    "func.slide3_t": "動的腎クリアランス CL(t) & 透析",
    "func.slide3_p": "敗血症・急性腎障害（AKI）において常微分方程式（ODE）を連続的に解き、蓄積質量 A₁(t)、A₂(t) の物理的連続性を保持。CRRT（CVVH/D/F）と間欠的血液透析をネイティブサポート。",
